const $=id=>document.getElementById(id), shuffle=a=>[...a].sort(()=>Math.random()-.5), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current=null,S={},timers=[],lastTrigger=null;
