function openGame(id){const g=GAMES.find(x=>x.id===id);if(!g)throw Error('Unknown game');lastTrigger=document.activeElement;current=g;$('gameTitle').textContent=g.en;$('gameMeta').textContent=`${g.mechanic} · ${g.age==='18+'?'Adults':'Ages '+g.age} · ${g.level}`;$('gameScene').style.backgroundImage=`linear-gradient(#14193955,#14193955),url(assets/bg${g.bg}.webp)`;$('mascot').src=`assets/hero${g.hero}.webp`;if(!$('gameDialog').open)$('gameDialog').showModal();start()}
function start(){cleanup();S={i:0,score:0,mistakes:0,locked:false};hud();render()}
function finish(total,label='correct answers'){cleanup();S.finished=true;const b=board('Round complete!','Restart to play again, or close this window to try another game.');b.append(el('div','score',`${S.score} / ${total}`),el('p','',label),btn('Play again',start,'primary'));hud('Well done — keep practising!')}
function advance(total){S.i++;S.locked=false;if(S.i>=total)finish(current.id==='gameshow'?total*100:total,current.id==='gameshow'?'game-show points':current.id==='cards'?'speaking prompts completed — self-assessed':current.id==='flashcards'?'cards recalled — self-assessed':'correct answers');else render()}
