const b=board(id==='imagequiz'?'What is this?':title,id==='gap'?'Choose the word or phrase that completes the sentence.':'Choose one answer. Read the explanation before moving on.');if(id==='imagequiz')b.append(el('div','picture',q[0]));if(id==='gameshow')b.append(el('p','timer','Round value: 100 points'));
const grid=el('div','answers');(id==='truefalse'||id==='pairno'?options:shuffle(options)).forEach(o=>{const button=btn(o,()=>{if(S.locked)return;button.classList.add(o===answer?'done':'wrong');grid.querySelectorAll('button').forEach(x=>{x.disabled=true;if(x.textContent===answer)x.classList.add('done')});if(S.questionClock)clearInterval(S.questionClock);answered(o===answer,explanation,qs.length,id==='gameshow'?100:1)});grid.append(button)});b.append(grid);
if(id==='gameshow'){let seconds=20;const clock=el('p','timer','20 seconds left');b.append(clock);S.questionClock=every(()=>{seconds--;clock.textContent=seconds+' seconds left';if(seconds<=0){clearInterval(S.questionClock);grid.querySelectorAll('button').forEach(x=>x.disabled=true);answered(false,'Time is up. '+explanation,qs.length,100)}},1000)}
