function pairs(){const memory=current.id==='memory',data=PAIRS[current.id];if(!S.cards){S.cards=shuffle(data.flatMap((p,i)=>p.map((text,side)=>({text,id:i,side,done:false}))));S.first=null;S.busy=false}const b=board(memory?'Find the opposite pairs':'Match each animal to its sound',memory?'Turn over two cards. Match opposite meanings.':'Choose two matching cards: an animal and its sound.');const grid=el('div','grid');S.cards.forEach((c,i)=>{const shown=!memory||c.done||S.first===i||S.second===i;const bt=btn(shown?c.text:'?',()=>{if(S.busy||c.done||S.first===i)return;if(S.first===null){S.first=i;pairs();return}S.second=i;S.busy=true;const prev=S.cards[S.first];if(prev.id===c.id){prev.done=c.done=true;S.score++;S.first=S.second=null;S.busy=false;if(S.score===data.length)return finish(data.length,'pairs found');pairs();feedback('A match!')}else{pairs();feedback('Try another pair.');later(()=>{S.first=S.second=null;S.busy=false;pairs()},850)}},`tile ${c.done?'done':shown?'':'face-down'}`,c.done);bt.setAttribute('aria-label',shown?c.text:'Hidden card '+(i+1));grid.append(bt)});b.append(grid);hud(`${S.score} / ${data.length} pairs`)}
function writing(){const mode=current.id,qs=WRITE[mode],q=qs[S.i];const b=board(q[0],mode==='anagram'?'Tap letters in order. Use Undo to remove the last letter.':'Type the English word, then check. Capital letters do not matter.');hud(`Word ${S.i+1} / ${qs.length} · Score ${S.score}`);if(mode==='anagram'){if(!S.letters){S.letters=shuffle(q[1].split('').map((letter,i)=>({letter,i})));S.used=[]}const out=el('div','large-word',S.used.map(i=>S.letters[i].letter).join('')||'…');b.append(out);const row=el('div','row');S.letters.forEach((l,i)=>row.append(btn(l.letter.toUpperCase(),()=>{S.used.push(i);writing()},'tile letter',S.used.includes(i)||S.locked)));b.append(row);b.append(btn('Undo',()=>{S.used.pop();writing()},'small',S.locked));b.append(btn('Check',()=>{if(S.used.length!==q[1].length){feedback('Use all the letters.');return}const ok=S.used.map(i=>S.letters[i].letter).join('')===q[1];if(ok){S.score++;S.locked=true;feedback('Correct!');b.append(btn('Next',()=>{S.letters=null;advance(qs.length)},'primary'))}else feedback('Not yet. Change the letter order and try again.')},'primary',S.locked));return}
const input=el('input','input');input.setAttribute('aria-label','Your answer');input.autocomplete='off';input.spellcheck=false;const check=()=>{if(!input.value.trim()){feedback('Enter a word first.');return}if(S.locked)return;input.disabled=true;answered(input.value.trim().toLowerCase()===q[1],`The word is “${q[1]}”.`,qs.length)};input.onkeydown=e=>{if(e.key==='Enter')check()};b.append(input,el('div','row'));b.lastChild.append(btn('Check',check,'primary'));if(mode==='spell')b.append(el('p','muted',`${q[1].length} letters`))}
function order(){const sentences=['Could I have a glass of water please?','I would like a table for two.','Could we see the menu please?'];const words=sentences[S.i].split(' ');if(!S.tokens){S.tokens=shuffle(words.map((w,i)=>({w,i})));S.used=[]}const b=board('Make a polite request','Tap the words in order. Undo removes the last word.');b.append(el('div','read-card',S.used.map(i=>S.tokens[i].w).join(' ')||'Your sentence will appear here'));const row=el('div','row');S.tokens.forEach((t,i)=>row.append(btn(t.w,()=>{S.used.push(i);order()},'tile',S.used.includes(i))));b.append(row,btn('Undo',()=>{S.used.pop();order()},'small'),btn('Check',()=>{const made=S.used.map(i=>S.tokens[i].w).join(' ');if(made===sentences[S.i]){S.score++;S.i++;S.tokens=null;S.i===sentences.length?finish(3):order()}else feedback('Not quite. Start with “Could” or “I” and use every word.')},'primary'));hud(`Request ${S.i+1} / 3`)}
function sort(){const items=[['apple','Food'],['dog','Animals'],['bread','Food'],['cat','Animals'],['cheese','Food'],['duck','Animals']];const q=items[S.i];const b=board(q[0],'Put the word into the correct group.');const row=el('div','answers');['Food','Animals'].forEach(c=>row.append(btn(c,()=>answered(c===q[1],`${q[0]} belongs in ${q[1]}.`,items.length))));b.append(row);hud(`Card ${S.i+1} / ${items.length}`)}
function wheel(){if(!S.remaining)S.remaining=[0,1,2,3,4,5];const b=board('Spin & speak','Spin the wheel, answer aloud, then mark the prompt complete.');const w=el('div','wheel');['Colours','Animals','Food','My bag','Skills','Family'].forEach((label,i)=>{const t=el('span','slice-label',label);t.style.transform=`rotate(${i*60+30}deg) translateY(-74px) rotate(-${i*60+30}deg)`;w.append(t)});b.append(el('div','wheel-pointer','▼'),w);const spin=btn('Spin',()=>{spin.disabled=true;const index=shuffle(S.remaining)[0];w.style.transform=`rotate(${1080-index*60-30}deg)`;later(()=>{b.append(el('div','read-card',SPEAK.wheel[index]),btn('I answered',()=>{S.remaining=S.remaining.filter(i=>i!==index);S.score++;S.remaining.length?wheel():finish(6,'speaking prompts completed — self-assessed')},'primary'));feedback('Say at least one full sentence.')},1250)},'primary');b.append(spin);hud(`${S.score} / 6 topics completed`)}
function cards(){const b=board(SPEAK.cards[S.i],'Answer aloud. Give a reason and an example. This activity is self-assessed.');const reveal=btn('Show a speaking starter',()=>{b.append(el('p','read-card','I would rather… because… For example,…'));reveal.disabled=true},'small');b.append(reveal,btn('I answered',()=>{S.score++;advance(SPEAK.cards.length)},'primary'));hud(`Card ${S.i+1} / ${SPEAK.cards.length}`)}
function boxes(){const tasks=['Name three things in a classroom.','Say two things you do every morning.','Ask your partner about their favourite food.','Describe the weather today.','Say one thing you can do well.','Make a sentence with “there is”.'];if(!S.opened)S.opened=[];const b=board('Choose a mystery box','Open a box, do the speaking task, then mark it complete.');const grid=el('div','grid');tasks.forEach((t,i)=>grid.append(btn(S.opened.includes(i)?'✓':String(i+1),()=>{board('Your mission','Say your answer aloud. There is no automatic speech scoring.');$('board').append(el('p','read-card',t),btn('Mission complete',()=>{S.opened.push(i);S.score++;S.opened.length===6?finish(6,'speaking missions completed — self-assessed'):boxes()},'primary'))},'tile card-number',S.opened.includes(i))));b.append(grid);hud(`${S.score} / 6 opened`)}
function flashcards(){const cards=[['boarding pass','A document that lets you get on a plane.'],['reservation','An arrangement to keep a room or seat for you.'],['luggage','Bags you take when travelling.'],['departure','The act or time of leaving.']];const b=board(cards[S.i][0],'Think of the meaning before turning the card. Rate your own recall.');const flip=btn('Turn card',()=>{flip.remove();b.append(el('p','read-card',cards[S.i][1]));const r=el('div','row');r.append(btn('I knew it',()=>{S.score++;advance(4)},'primary'),btn('Practise again',()=>advance(4),'tile'));b.append(r)},'primary');b.append(flip);hud(`Card ${S.i+1} / 4`)}
function wordsearch(){const rows=['TREEQWAS','ZQPLMNOP','RIVERABC','ZXCVBNML','FLOWERXY','PQSTUVWX','SUNABCDF','GHJKLMNO'];const words=['TREE','RIVER','FLOWER','SUN'];if(!S.found){S.found=[];S.anchor=null}const b=board('Find four nature words','Select the first and last letter of a word. All words read left to right.');b.append(el('p','',words.map(w=>S.found.includes(w)?'✓ '+w:w).join(' · ')));const grid=el('div','word-grid');rows.forEach((r,y)=>r.split('').forEach((c,x)=>{const found=S.found.some(w=>rows.indexOf(rows.find(v=>v.startsWith(w)))===y&&x<w.length);const bt=btn(c,()=>{if(!S.anchor){S.anchor={x,y};wordsearch();return}const a=S.anchor;S.anchor=null;const word=a.y===y?rows[y].slice(Math.min(a.x,x),Math.max(a.x,x)+1):'';if(words.includes(word)&&!S.found.includes(word)){S.found.push(word);S.score++;if(S.found.length===4)return finish(4,'words found')}wordsearch();feedback(words.includes(word)?'Word found!':'Choose the first and last letters in the same row.')},found?'done':S.anchor?.x===x&&S.anchor?.y===y?'selected':'');bt.setAttribute('aria-label',`${c}, row ${y+1}, column ${x+1}`);grid.append(bt)}));b.append(grid);hud(`${S.score} / 4 words`)}
function crossword(){const solution=['CAT','ANT','RAT'];const b=board('Complete the crossword','Fill the nine squares. Clues share letters.');const grid=el('div','crossword');grid.style.gridTemplateColumns='repeat(3,1fr)';solution.forEach((row,y)=>row.split('').forEach((c,x)=>{const input=el('input');input.maxLength=1;input.autocomplete='off';input.setAttribute('aria-label',`Row ${y+1}, column ${x+1}`);input.dataset.answer=c;grid.append(input)}));b.append(grid,el('p','small','Across: 1 (top) — a pet that says “meow”. 2 (middle) — a tiny insect. 3 (bottom) — a rodent, larger than a mouse.'),el('p','small','Down: first column — a vehicle with four wheels.'),btn('Check puzzle',()=>{const inputs=[...grid.children];let count=0;inputs.forEach(e=>{const good=e.value.toUpperCase()===e.dataset.answer;e.style.background=good?'#d5f779':'#ffcec8';if(good)count++});if(count===9){S.score=4;finish(4,'words completed')}else feedback(`${count} of 9 letters correct. Pink squares need another try.`)},'primary'));hud('3 across + 1 down')}
function rank(){const correct=['Dear Ms Taylor,','I am writing to ask about the course.','Could you send me the timetable?','Thank you for your help.','Best regards, Alex'];if(!S.order)S.order=shuffle(correct);const b=board('Put the email in order','Use Up and Down to move each line, then check.');const list=el('div','order-list');S.order.forEach((t,i)=>{const row=el('div','order-item');row.append(el('span','',t),btn('↑',()=>{[S.order[i-1],S.order[i]]=[S.order[i],S.order[i-1]];rank()},'',i===0),btn('↓',()=>{[S.order[i+1],S.order[i]]=[S.order[i],S.order[i+1]];rank()},'',i===4));row.children[1].setAttribute('aria-label','Move line '+(i+1)+' up');row.children[2].setAttribute('aria-label','Move line '+(i+1)+' down');list.append(row)});b.append(list,btn('Check order',()=>{if(S.order.every((s,i)=>s===correct[i])){S.score=5;finish(5,'lines in the right order')}else feedback('Start with the greeting and end with your name. Try again.')},'primary'));hud('5 lines')}
const MAZE=['.......','.###.#.','...#...','.#...#.','...#...','.###.#.','.......'];
function maze(){if(!S.pos)S.pos={x:0,y:0};const targets=[{x:6,y:0,text:'red',color:'#e55970'},{x:0,y:6,text:'blue',color:'#579de5'},{x:6,y:6,text:'green',color:'#62ba83'}];const goal=['blue','red','green'][S.i];const b=board('Find '+goal,'Use the arrow buttons or arrow keys. You can also tap a neighbouring square.');const grid=el('div','maze');MAZE.forEach((r,y)=>r.split('').forEach((c,x)=>{const t=targets.find(t=>t.x===x&&t.y===y);const cell=btn(t?t.text:'',()=>{if(Math.abs(x-S.pos.x)+Math.abs(y-S.pos.y)===1)move(x-S.pos.x,y-S.pos.y)},c==='#'?'wall':'',c==='#');cell.setAttribute('aria-label',c==='#'?'Wall':t?t.text:`Row ${y+1}, column ${x+1}`);if(t){cell.style.background=t.color;cell.style.color='#fff'}if(S.pos.x===x&&S.pos.y===y){cell.textContent='';const img=el('img');img.src=`assets/hero${current.hero}.webp`;img.alt='You';cell.append(img)}grid.append(cell)}));b.append(grid);const controls=el('div','row');[['↑',0,-1],['←',-1,0],['↓',0,1],['→',1,0]].forEach(([l,x,y])=>controls.append(btn(l,()=>move(x,y),'tile')));b.append(controls);hud(`Target ${S.i+1} / 3`);
function move(dx,dy){const x=S.pos.x+dx,y=S.pos.y+dy;if(x<0||x>6||y<0||y>6||MAZE[y][x]==='#')return;S.pos={x,y};const t=targets.find(t=>t.x===x&&t.y===y);if(t?.text===goal){S.score++;S.i++;if(S.i===3)return finish(3,'colours reached');maze();feedback('You found '+goal+'!')}else{maze();if(t)feedback('That is '+t.text+'. Find '+goal+'.')}}document.onkeydown=e=>{const d={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[e.key];if(d){e.preventDefault();move(...d)}}}
function airplane(){const qs=[['go','went',['went','goed','gone']],['see','saw',['seen','saw','seed']],['eat','ate',['eated','eaten','ate']]];const q=qs[S.i];S.lane=1;S.flyX=72;S.flying=false;const options=shuffle(q[2]);const b=board('Past simple of “'+q[0]+'”','Move up or down to the correct lane, then fly. You can keep changing lanes during flight.');const field=el('div','flight');const pilot=el('img','pilot');pilot.src=`assets/hero${current.hero}.webp`;pilot.alt='Your pilot';pilot.style.top='76px';field.append(pilot);const clouds=options.map((o,i)=>{const c=el('div','cloud',o);c.style.top=(i*70+5)+'px';c.style.animation='none';c.style.left='72%';c.style.width='25%';c.style.padding='15px 2px';field.append(c);return c});b.append(field);const move=d=>{if(S.locked)return;S.lane=Math.max(0,Math.min(2,S.lane+d));pilot.style.top=(S.lane*70+6)+'px'};const controls=el('div','row');controls.append(btn('Up',()=>move(-1),'tile'),btn('Down',()=>move(1),'tile'));const fly=btn('Fly',()=>{if(S.flying)return;S.flying=true;fly.disabled=true;const timer=every(()=>{S.flyX-=1.2;clouds.forEach(c=>c.style.left=S.flyX+'%');if(S.flyX<=16){clearInterval(timer);const answer=options[S.lane];answered(answer===q[1],`The past simple of “${q[0]}” is “${q[1]}”.`,3)}},70)},'primary');controls.append(fly);b.append(controls);document.onkeydown=e=>{if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();move(e.key==='ArrowUp'?-1:1)}};hud(`Flight ${S.i+1} / 3`)}
function whack(){if(S.wave===undefined)S.wave=0;const waves=[['run','hat','red'],['blue','jump','desk'],['book','green','swim'],['sing','chair','yellow'],['pink','shoe','dance']];const verbs=['run','jump','swim','sing','dance'];if(S.wave>=5)return finish(5,'verbs caught');const b=board('Catch the verb!','Tap the action word before it disappears. Each wave lasts five seconds.');const holes=el('div','holes');let done=false;const settle=word=>{if(done)return;done=true;clearTimeout(S.waveTimer);const ok=word===verbs[S.wave];if(ok)S.score++;feedback(ok?'Caught! '+word+' is an action.':word?'The verb was “'+verbs[S.wave]+'”.':'Too slow! The verb was “'+verbs[S.wave]+'”.');holes.querySelectorAll('button').forEach(x=>x.disabled=true);b.append(btn('Next wave',()=>{S.wave++;whack()},'primary'))};shuffle([...waves[S.wave],'','','']).forEach((w,i)=>{const bt=btn(w||'·',()=>settle(w),w?'up':'',!w);bt.setAttribute('aria-label',w||'Empty hole '+(i+1));holes.append(bt)});b.append(holes);S.waveTimer=later(()=>settle(null),5000);hud(`Wave ${S.wave+1} / 5 · Score ${S.score}`)}
function balloon(){if(!S.popped)S.popped=[];const words=['apple','chair','bread','ball','cheese','book'];const foods=['apple','bread','cheese'];const b=board('Pop the food balloons','Pop food words so they drop into the basket. Leave the other words.');const row=el('div','balloons');words.forEach((w,i)=>{if(S.popped.includes(w))return;const bt=btn(w,()=>{if(foods.includes(w)){if(S.busy)return;S.busy=true;bt.style.animation='none';bt.style.transition='transform .35s,opacity .35s';bt.style.transform='translateY(85px) scale(.6)';bt.style.opacity='0';later(()=>{S.popped.push(w);S.score++;S.busy=false;if(S.score===3)return finish(3,'food words collected');balloon();feedback(w+' is in the basket!')},350)}else{bt.classList.add('wrong');feedback(w+' is not food. Leave that balloon.')}},'balloon');bt.style.animationDelay=(i*.25)+'s';row.append(bt)});b.append(row,el('div','read-card','Basket: '+(S.popped.join(' · ')||'empty')));hud(`${S.score} / 3 food words`)}
function hangman(){const word='dentist';if(!S.guesses)S.guesses=[];const wrong=S.guesses.filter(c=>!word.includes(c));const b=board('This person looks after your teeth.','Choose letters. You have six incorrect guesses.');b.append(el('div','large-word',word.split('').map(c=>S.guesses.includes(c)?c.toUpperCase():'_').join(' ')),el('p','',`${6-wrong.length} guesses left`));if(word.split('').every(c=>S.guesses.includes(c))){S.score=1;return finish(1,'mystery word solved: DENTIST')}if(wrong.length>=6){S.score=0;return finish(1,'The word was DENTIST. Try again!')}const keys=el('div','alphabet');'abcdefghijklmnopqrstuvwxyz'.split('').forEach(c=>keys.append(btn(c.toUpperCase(),()=>{S.guesses.push(c);hangman()},'tile',S.guesses.includes(c))));b.append(keys);hud('Mystery job')}
function diagram(){const labels=['library','hospital','supermarket','park'];if(!S.labels)S.labels={};const b=board('Label the town map','Choose a place name, then choose the matching description on the map.');const choices=el('div','row');labels.forEach(l=>choices.append(btn(l,()=>{S.label=l;diagram()},S.label===l?'tile selected':'tile',Object.values(S.labels).includes(l))));b.append(choices);const map=el('div','map');const clues=['Borrow books','See a doctor','Buy food','Walk among trees'];clues.forEach((c,i)=>{const bt=btn(S.labels[i]||c,()=>{if(!S.label){feedback('Choose a place name first.');return}if(S.label===labels[i]){S.labels[i]=S.label;S.label=null;S.score++;if(S.score===4)return finish(4,'places labelled');diagram();feedback('Correct place!')}else feedback('Try another place. '+c+'.')},S.labels[i]?'done':'',!!S.labels[i]);bt.style.left=i%2?'60%':'5%';bt.style.top=i<2?'18px':'150px';map.append(bt)});b.append(map);hud(`${S.score} / 4 labels`)}
function watch(){const words=['pencil','book','ruler','bag'];const b=board('Look at the tray','Look carefully. When you are ready, hide the tray and remember the words.');b.append(el('div','read-card',words.join(' · ')),btn('I am ready — hide the tray',()=>{const b=board('Which words were on the tray?','Select four words, then check.');const picked=new Set();const choices=el('div','answers');shuffle([...words,'apple','shoe','hat','ball']).forEach(w=>{const bt=btn(w,()=>{if(picked.has(w))picked.delete(w);else if(picked.size<4)picked.add(w);bt.classList.toggle('selected',picked.has(w));feedback(`${picked.size} / 4 selected`)});choices.append(bt)});b.append(choices,btn('Check memory',()=>{if(picked.size!==4){feedback('Select exactly four words.');return}S.score=[...picked].filter(w=>words.includes(w)).length;finish(4,'remembered correctly. The tray held: pencil, book, ruler, bag.')},'primary'))},'primary'));hud('Look, hide, remember')}
function speed(){const qs=[['A week has seven days.','Fact'],['Summer is the best season.','Opinion'],['Water freezes at 0°C at standard pressure.','Fact'],['Online lessons are more enjoyable.','Opinion'],['London is in the UK.','Fact'],['Cats make better pets than dogs.','Opinion']];if(!S.speedStarted){S.speedStarted=true;S.seconds=45;S.clock=every(()=>{S.seconds--;hud(`Time ${S.seconds}s · Score ${S.score}`);if(S.seconds<=0){finish(6,'correctly sorted before time ran out')}},1000)}const b=board(qs[S.i][0],'Choose Fact or Opinion. Sort all six statements before the 45-second timer ends.');const row=el('div','answers');['Fact','Opinion'].forEach(c=>row.append(btn(c,()=>{const ok=c===qs[S.i][1];if(ok)S.score++;S.i++;if(S.i===qs.length)return finish(6,'statements sorted correctly');speed();feedback(ok?'Correct!':'Previous statement: '+qs[S.i-1][1]+'.')})));b.append(row);hud(`Time ${S.seconds}s · Card ${S.i+1} / 6`)}
function riskquiz(){const qs=[{points:100,q:'If I ___ you, I would apologise.',a:'were',opts:['am','were','will be'],why:'Use “were” in this second conditional.'},{points:200,q:'By next July, I ___ here for ten years.',a:'will have worked',opts:['will have worked','will work','have worked'],why:'Future perfect looks back from a future point.'},{points:300,q:'Not only ___ late, but he also forgot the report.',a:'was he',opts:['he was','was he','he is'],why:'After initial “Not only”, use inversion.'}];if(!S.played)S.played=[];const b=board('Choose the next challenge','A correct answer adds the value. A wrong answer subtracts it. These are game points only.');hud(`Points: ${S.score}`);const row=el('div','row');qs.forEach((q,i)=>row.append(btn(String(q.points)+' points',()=>{const b=board(q.q,'Choose one answer.');const answers=el('div','answers');let done=false;q.opts.forEach(o=>answers.append(btn(o,()=>{if(done)return;done=true;S.played.push(i);S.score+=o===q.a?q.points:-q.points;hud(`Points: ${S.score}`);feedback((o===q.a?'Correct! +':'Not quite. −')+q.points+' points. '+q.why);answers.querySelectorAll('button').forEach(x=>x.disabled=true);b.append(btn('Continue',()=>{if(S.played.length===3){const b=board('Challenge complete!','You can restart to practise again.');b.append(el('div','score',String(S.score)),el('p','','game points · maximum 600'),btn('Play again',start,'primary'));hud('All three challenges completed')}else riskquiz()},'primary'))})));b.append(answers)},'tile',S.played.includes(i))));b.append(row)}
$('age').onchange=catalog;$('closeGame').onclick=()=>$('gameDialog').close();$('restart').onclick=start;$('gameDialog').addEventListener('close',()=>{cleanup();lastTrigger?.focus()});$('gameDialog').addEventListener('click',e=>{if(e.target===$('gameDialog')){const r=$('gameDialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('gameDialog').close()}});catalog();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_english_games',description:'List the 30 English game examples with mechanics, ages and levels.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>GAMES.map(({id,en,mechanic,age,level})=>({id,title:en,mechanic,age,level}))})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'open_english_game',description:'Open and restart a playable English game example. This does not complete or answer the game.',inputSchema:{type:'object',properties:{id:{type:'string',enum:GAMES.map(g=>g.id)}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!GAMES.some(g=>g.id===input.id))throw Error('Unknown game ID');openGame(input.id);return {opened:current.id,title:current.en}}})).catch(()=>{})}catch{}}
